function GlassColorantMortarMaker.init() GlassColorantMortarMaker.ironStock=16; GlassColorantMortarMaker.bronzeStock=14; GlassColorantMortarMaker.woodStock=10; GlassColorantMortarMaker.leatherStock=8; GlassColorantMortarMaker.silverStock=8; GlassColorantMortarMaker.goldStock=6; GlassColorantMortarMaker.jewelStock=4; GlassColorantMortarMaker.pearlStock=4; GlassColorantMortarMaker.productStock={}; GlassColorantMortarMaker.buildings={}; GlassColorantMortarMaker.maker=nil; GlassColorantMortarMaker.activeMaking={}; GlassColorantMortarMaker.totalProducts=0; GlassColorantMortarMaker.dayTimer=0; print("[GlassColorantMortarMaker] Royal Glass Colorant Mortar Maker System initialized (6 products, 4 buildings)") end
function GlassColorantMortarMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassColorantMortarMaker.maker={name=n or ("Možnarar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Možnarar najet: %s (spretnost: %d)",GlassColorantMortarMaker.maker.name,s),"success") end; return true end
function GlassColorantMortarMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassColorantMortarMaker.build(id) local ok,e=GlassColorantMortarMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassColorantMortarMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassColorantMortarMaker.getQualityBonus() local b=0; for _,bd in ipairs(GlassColorantMortarMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassColorantMortarMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GlassColorantMortarMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GlassColorantMortarMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GlassColorantMortarMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GlassColorantMortarMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GlassColorantMortarMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassColorantMortarMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassColorantMortarMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassColorantMortarMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassColorantMortarMaker.buildings==0 then return false,"Potrebna možnarska delavnica" end; if not GlassColorantMortarMaker.maker then return false,"Potreben možnarar" end; return true end
function GlassColorantMortarMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassColorantMortarMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassColorantMortarMaker.ironStock=GlassColorantMortarMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassColorantMortarMaker.bronzeStock=GlassColorantMortarMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassColorantMortarMaker.woodStock=GlassColorantMortarMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassColorantMortarMaker.leatherStock=GlassColorantMortarMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassColorantMortarMaker.silverStock=GlassColorantMortarMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassColorantMortarMaker.goldStock=GlassColorantMortarMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassColorantMortarMaker.jewelStock=GlassColorantMortarMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassColorantMortarMaker.pearlStock=GlassColorantMortarMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassColorantMortarMaker.maker then t=math.max(1,t-math.floor(GlassColorantMortarMaker.maker.skill/13)) end; table.insert(GlassColorantMortarMaker.activeMaking,{id="glasscolorantmortar_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassColorantMortarMaker.completeMaking(m) local q=1.0+(GlassColorantMortarMaker.getQualityBonus()/100); if GlassColorantMortarMaker.maker then q=q+(GlassColorantMortarMaker.maker.skill/140) end; q=math.min(2.5,q); GlassColorantMortarMaker.productStock[m.productType]=(GlassColorantMortarMaker.productStock[m.productType] or 0)+m.quantity; GlassColorantMortarMaker.totalProducts=GlassColorantMortarMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassColorantMortarMaker.maker then GlassColorantMortarMaker.maker.itemsMade=GlassColorantMortarMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassColorantMortarMaker.maker.skill=math.min(100,GlassColorantMortarMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Možnar izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glasscolorantmortar.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassColorantMortarMaker.update(dt) if not _G.state then return end; GlassColorantMortarMaker.dayTimer=GlassColorantMortarMaker.dayTimer+dt; if GlassColorantMortarMaker.dayTimer>=30 then GlassColorantMortarMaker.dayTimer=0; for i=#GlassColorantMortarMaker.activeMaking,1,-1 do local m=GlassColorantMortarMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassColorantMortarMaker.completeMaking(m); table.remove(GlassColorantMortarMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassColorantMortarMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassColorantMortarMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GlassColorantMortarMaker.getStats() return {ironStock=GlassColorantMortarMaker.ironStock,bronzeStock=GlassColorantMortarMaker.bronzeStock,woodStock=GlassColorantMortarMaker.woodStock,leatherStock=GlassColorantMortarMaker.leatherStock,silverStock=GlassColorantMortarMaker.silverStock,goldStock=GlassColorantMortarMaker.goldStock,jewelStock=GlassColorantMortarMaker.jewelStock,pearlStock=GlassColorantMortarMaker.pearlStock,productStock=GlassColorantMortarMaker.productStock,numBuildings=#GlassColorantMortarMaker.buildings,hasMaker=GlassColorantMortarMaker.maker~=nil,makerName=GlassColorantMortarMaker.maker and GlassColorantMortarMaker.maker.name or "—",makerSkill=GlassColorantMortarMaker.maker and GlassColorantMortarMaker.maker.skill or 0,activeMaking=#GlassColorantMortarMaker.activeMaking,totalProducts=GlassColorantMortarMaker.totalProducts} end
